package mom

import "strings"

// ServiceGroup returns this implementation's deterministic normalization.
// The numeric assignment follows the existing binding's zero-based group enum;
// it is not a claim that the standard prescribes particular normalized numbers.
func ServiceGroup(service string) (uint64, bool) {
	group, known := serviceGroups[service]
	return group, known
}

// The catalog is immutable; parsing it for every observed service adds work to
// both LocalLRC operations and callback accounting.
var serviceGroups = func() map[string]uint64 {
	groups := make(map[string]uint64)
	for group, names := range serviceGroupNames {
		for _, name := range strings.Fields(names) {
			if _, exists := groups[name]; !exists {
				groups[name] = uint64(group)
			}
		}
	}
	return groups
}()

